// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // The owner is address(this) from setUp
        vm.assume(amount > 0); // avoid zero edge case
        c.AdjustDifficulty(amount);
        // The general rule: the public getter returns the amount set
        assertTrue(c.currentDifficulty() == amount);
    }
}

